// One item per brand. Listed here rather than fetched so a brand can be
// paused by editing one line, without a deploy.
//
// Arak only: it is the one workspace with an email list. The handler skips a
// workspace with no marketing contacts anyway, so adding one here that has no
// list costs nothing until it has one.
return [
  { json: { workspace_id: '00000000-0000-0000-0000-000000000001', name: 'Arak Lighting' } },
];

// The line a person reads when checking on this in n8n.
// $input, not $json: this Code node runs once for all items, where $json
// is not defined.
const r = $input.first().json || {};
const code = r.statusCode || (r.ok === false ? 'error' : 200);
const bits = [
  r.ok === true && r.skipped ? `Skipped: ${r.skipped}` : '',
  r.ok === true && !r.skipped ? `Wrote ${r.options} draft option(s) for the week of ${r.week_of}` : '',
  r.ok === false ? `Not written (${code}): ${r.error || 'unknown error'}` : '',
  r.capped ? 'The workspace hit its monthly AI budget.' : '',
  r.cost != null ? `$${Number(r.cost).toFixed(3)}` : '',
].filter(Boolean);
return [{ json: { summary: bits.join(' · ') || 'No answer from the agent.', ...r } }];

const expected = String($env.N8N_WEBHOOK_SECRET || '').trim();
if (expected) {
  const headers = ($input.first().json || {}).headers || {};
  const got = String(headers['x-webhook-secret'] || headers['X-Webhook-Secret'] || '').trim();
  if (got !== expected) throw new Error('Unauthorized: missing or invalid webhook secret');
}
return $input.all();

const body = ($input.first().json || {}).body || {};
const accessToken = String(body.access_token || '').trim();
const workspaceId = String(body.workspace_id || '').trim();

if (!accessToken) {
  return [{ json: { ok: false, error: 'Sign in to do this.' } }];
}

// The browser token goes only to the private agent container, which checks
// that this person belongs to the workspace. n8n never trusts the workspace
// id in this body by itself. One route, fixed here: this gateway is not a
// general proxy to the agent.
try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: `${$env.AGENT_BASE_URL}/api/agent/emailWeekly`,
    headers: { Authorization: `Bearer ${accessToken}`, 'Content-Type': 'application/json' },
    body: { workspace_id: workspaceId, trigger: 'manual' },
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    // One Sonnet call plus the reads before it. Well under the app proxy's
    // 300s, so the browser hears an answer rather than a gateway timeout.
    timeout: 240000,
  });
  const payload = response?.body && typeof response.body === 'object'
    ? response.body
    : { ok: false, error: `The agent returned ${response?.statusCode || 'an empty response'}.` };
  return [{ json: payload }];
} catch (err) {
  return [{ json: { ok: false, error: `Could not reach the agent: ${err.message}` } }];
}
